use genex::prelude::*;
use genex::render::Decal;

/// Wear the wall's own texture cannot carry: a damp band at the floor, streaks under a sill, a stain.
fn draw_grime(frame: &mut Frame, wall: &WallRun) {
    frame.tag("grime");
    let base = wall.mid + vec3(0.0, 0.35 - wall.height * 0.5, 0.0);
    frame.decal(&Decal::on_wall(base, wall.facing, wall.length, 0.7).with_base_texture("decals/damp-band.png").with_opacity(0.8));
    for sill in &wall.sills {
        frame.decal(
            &Decal::on_wall(*sill - vec3(0.0, 0.6, 0.0), wall.facing, 0.9, 1.2)
                .with_base_texture("decals/streaks.png")
                .with_normal_texture("decals/streaks-normal.png", 0.6)
                .with_roughness(0.85),
        );
    }
}
